import os, subprocess, sqlite3, shutil, pathlib
def test(size):
    d=f'/tmp/vt_{size}'
    shutil.rmtree(d, ignore_errors=True)
    os.makedirs(d)
    with open(os.path.join(d,'f'),'wb') as fh:
        fh.truncate(size)
    db=f'/tmp/vt_{size}.db'
    try: os.remove(db)
    except: pass
    subprocess.run(['./executable','index','-d',db,d], check=True, capture_output=True)
    con=sqlite3.connect(db)
    for k,v in con.execute("SELECT key,value FROM blobs"):
        if '/' in k and not k.startswith('/tmp'):
            print(size, k, v.hex(' '))
    con.close()
for s in [0,1,2,127,128,200,255,256,257,511,512,1000,4095,4096,4097,5000,5009,8192,12288,65535,65536,100000, 1000000]:
    test(s)
PY"}

