VERSION_TEXT = b"duc version: 1.5.0-rc1\noptions: cairo x11 ui sqlite3\n"

# ---------------------------------------------------------------------------
# Small utilities / C-compatible conversions

def bstr(x):
    if isinstance(x, bytes):
        return x
    return str(x).encode()

def out(data):
    if isinstance(data, str):
        data = data.encode()
    try:
        sys.stdout.buffer.write(data)
    except BrokenPipeError:
