def segfault():
    try:
        sys.stdout.buffer.flush(); sys.stderr.buffer.flush()
    except Exception:
        pass
    os.kill(os.getpid(), signal.SIGSEGV)
    os._exit(139)

def c_atoi(v, bits=32):
    if v is None:
        segfault()
    if isinstance(v, int):
        n = v
    else:
        s = bytes(v)
        i = 0
        while i < len(s) and s[i] in b' \t\n\v\f\r':
            i += 1
        sign = 1
        if i < len(s) and s[i:i+1] in (b'+', b'-'):
            if s[i:i+1] == b'-': sign = -1
            i += 1
        n = 0; seen = False
        while i < len(s) and 48 <= s[i] <= 57:
            seen = True
