class Logger:
    def __init__(self):
        self.level = LOG_WARNING
        self.progress = False
    def set_from_opts(self, opts):
        if opts.get('debug'):
            self.level = LOG_DEBUG
        elif opts.get('verbose'):
            self.level = LOG_INFO
