def parse_cli(opts, cmd, args, prog):
    specs = all_opts(cmd)
    short_map = {}
    long_list = []
    for o in GLOBAL_OPTS + CMD_OPTS[cmd]:
        # Order observable in ambiguity messages is complicated; for normal
        # unambiguous parsing the order does not matter.
        pass
    for o in specs:
        if o.short is not None:
            short_map[o.short] = o
        long_list.append(o)
    positionals = []
    i = 0
    end_opts = False
    posix = b'POSIXLY_CORRECT' in getattr(os, 'environb', {})
    while i < len(args):
        arg = args[i]; i += 1
        if end_opts or arg == b'-' or not arg.startswith(b'-') or arg == b'':
            positionals.append(arg)
            if posix and not end_opts:
                positionals.extend(args[i:]); break
            continue
        if arg == b'--':
            end_opts = True
            continue
        if arg.startswith(b'--'):
            body = arg[2:]
            if b'=' in body:
                name, eqval = body.split(b'=', 1); has_eq = True
            else:
                name, eqval, has_eq = body, None, False
            exact = [o for o in long_list if o.long == name]
            if exact:
                chosen = exact[0]
            else:
                cand = [o for o in long_list if o.long.startswith(name)] if name != b'' else list(long_list)
                # De-duplicate by long name, preserving order.
                seen = set(); uniq = []
                for o in cand:
                    if o.long not in seen:
                        seen.add(o.long); uniq.append(o)
                cand = uniq
                if len(cand) == 0:
                    raise getopt_error(prog, b"unrecognized option '" + arg + b"'")
                if len(cand) > 1:
                    poss = b' '.join(b"'--" + o.long + b"'" for o in cand)
                    raise getopt_error(prog, b"option '" + arg + b"' is ambiguous; possibilities: " + poss)
                chosen = cand[0]
            if chosen.arg:
                if has_eq:
                    value = eqval
                elif i < len(args):
                    value = args[i]; i += 1
                else:
                    raise getopt_error(prog, b"option '--" + chosen.long + b"' requires an argument")
                store_opt(opts, chosen, value)
            else:
                if has_eq:
                    raise getopt_error(prog, b"option '--" + chosen.long + b"' doesn't allow an argument")
                store_opt(opts, chosen, True)
            continue
        # short options
        cluster = arg[1:]
        j = 0
        while j < len(cluster):
            ch = cluster[j:j+1]; j += 1
            o = short_map.get(ch)
            if o is None:
                raise getopt_error(prog, b"invalid option -- '" + ch + b"'")
            if o.arg:
                if j < len(cluster):
                    value = cluster[j:]; j = len(cluster)
                elif i < len(args):
                    value = args[i]; i += 1
                else:
                    raise getopt_error(prog, b"option requires an argument -- '" + ch + b"'")
                store_opt(opts, o, value)
            else:
                store_opt(opts, o, True)
    return positionals

