def open_db(path, write=False):
    # Returns DB or raises DBOpenError(kind, secondary)
    if path == b'':
        raise DBOpenError(UNSUPPORTED, b'No error: success')
    if not write and path in (b':memory:',) :
        raise DBOpenError(UNSUPPORTED, b'No error: success')
    if path.startswith(b'file:'):
        # The original mis-handles SQLite URIs; treat as unsupported here.
        raise DBOpenError(UNSUPPORTED, b'No error: success')
    path_str = path.decode('utf-8', 'surrogateescape')
    if write and path == b':memory:':
        con = sqlite3.connect(':memory:')
        db = DB(path, con); db.create_tables(); db.commit(); return db
    exists = os.path.lexists(path)
    if not write:
        if not os.path.exists(path):
            raise DBOpenError(NOT_FOUND, NOT_FOUND)
        if os.path.isdir(path):
            raise DBOpenError(CORRUPT, CORRUPT)
        try:
            sz = os.path.getsize(path)
        except Exception:
            raise DBOpenError(NOT_FOUND, NOT_FOUND)
        if sz < 2:
            raise DBOpenError(UNSUPPORTED, b'No error: success')
        if not _sqlite_validate_file(path):
            raise DBOpenError(CORRUPT, CORRUPT)
        con = sqlite3.connect(path_str)
        return DB(path, con)
    else:
        # write / index
        if os.path.isdir(path):
            raise DBOpenError(NOT_FOUND, NOT_FOUND)
        if exists:
            try:
                sz = os.path.getsize(path)
            except Exception:
                raise DBOpenError(NOT_FOUND, NOT_FOUND)
            if sz >= 2 and not _sqlite_validate_file(path):
                raise DBOpenError(CORRUPT, CORRUPT)
            try:
                con = sqlite3.connect(path_str)
                # Force header handling for 0/1-byte files by creating tables.
                db = DB(path, con)
                db.create_tables(); db.commit()
                return db
            except DBOpenError:
                raise
            except Exception:
                # 1-byte files can confuse some sqlite builds; recreate.
                try:
                    os.remove(path)
                    con = sqlite3.connect(path_str)
                    db = DB(path, con); db.create_tables(); db.commit(); return db
                except Exception:
                    raise DBOpenError(CORRUPT, CORRUPT)
        else:
            try:
                con = sqlite3.connect(path_str)
            except Exception:
                raise DBOpenError(NOT_FOUND, NOT_FOUND)
            db = DB(path, con); db.create_tables(); db.commit(); return db

