    env = getattr(os, 'environb', None)
    if env is not None and b'DUC_DATABASE' in env:
        return env[b'DUC_DATABASE']
    if 'DUC_DATABASE' in os.environ:
        return os.environ['DUC_DATABASE'].encode()
    if env is not None and b'XDG_CACHE_HOME' in env:
        return join_path(env[b'XDG_CACHE_HOME'] if env[b'XDG_CACHE_HOME'] else b'', b'duc/duc.db') if env[b'XDG_CACHE_HOME'] else b'/duc/duc.db'
    if 'XDG_CACHE_HOME' in os.environ:
        x = os.environ['XDG_CACHE_HOME'].encode()
        return (x + b'/duc/duc.db') if x else b'/duc/duc.db'
    h = home_bytes()
    if h is None:
        return b'/.cache/duc/duc.db'
    return join_path(h, b'.cache/duc/duc.db')

