DB_DUP = {'info': True, 'xml': True, 'json': True, 'histogram': True, 'topn': True, 'graph': True, 'index': True, 'ls': False, 'ui': False, 'gui': False, 'cgi': True, 'help': False}

def open_db_for(cmd, opts, write=False):
    path = default_db_path(opts)
    if write:
        log.info(b'Writing to database "' + path + b'"\n')
    else:
        log.info(b'Reading from database "' + path + b'"\n')
    try:
        return open_db(path, write=write)
    except DBOpenError as e:
        print_db_error(path, e, DB_DUP.get(cmd, False))
        return None

