# ---------------------------------------------------------------------------
# Directory lookup / entry sorting for queries
TYPE_BLK, TYPE_CHR, TYPE_DIR, TYPE_FIFO, TYPE_LNK, TYPE_REG, TYPE_SOCK, TYPE_UNKNOWN = 0, 1, 2, 3, 4, 5, 6, 7

def classify_char(t):
    return {0: b'%', 1: b'%', 2: b'/', 3: b'|', 4: b'>', 5: b' ', 6: b'@', 7: b'?'}.get(t, b' ')

def ent_value(e, mode):
    if mode == 'apparent': return e.size_apparent
    if mode == 'count': return e.count
    return e.size_actual

def sorted_entries(entries, mode='actual', name_sort=False):
    if name_sort:
        return sorted(entries, key=lambda e: e.name)
    if mode == 'apparent':
        return sorted(entries, key=lambda e: (-e.size_apparent, -e.size_actual, e.name))
    if mode == 'count':
        return sorted(entries, key=lambda e: (-e.count, e.name))
    return sorted(entries, key=lambda e: (-e.size_actual, -e.size_apparent, e.name))

class PathLookup:
    def __init__(self, dir_obj=None, report=None, no_report=False):
        self.dir = dir_obj
        self.report = report
        self.no_report = no_report

def find_dir(db, norm_path, log_no_report=True):
    paths = db.report_paths()
    cand = []
    for rp in paths:
        if rp == b'/':
            cand.append(rp)
        elif norm_path == rp or norm_path.startswith(rp.rstrip(b'/') + b'/'):
            cand.append(rp)
    if not cand:
        if log_no_report:
            err(b'Path ' + norm_path + b' not found in database\n')
        return PathLookup(None, None, True)
    # Try candidates in stored report order (longer candidates that fail do
    # not prevent another report from being tried below when the first
    # matching report is not a component-wise ancestor).
    first_failed = None
    for rp in cand:
        rep = db.get_report(rp)
        if rep is None:
            continue
        root = db.get_dir(rep.dev, rep.ino)
        if root is None:
            first_failed = PathLookup(None, rep, False)
            continue
        rest = norm_path[len(rp.rstrip(b'/')):] if rp != b'/' else norm_path
        comps = [c for c in rest.split(b'/') if c]
        cur = root; ok = True
        for c in comps:
            ent = None
            for e in cur.entries:
                if e.name == c:
                    ent = e; break
            if ent is None or ent.type != TYPE_DIR:
                ok = False; break
            nxt = db.get_dir(ent.dev, ent.ino)
            if nxt is None:
                ok = False; break
            cur = nxt
        if ok:
            return PathLookup(cur, rep, False)
        if first_failed is None:
            first_failed = PathLookup(None, rep, False)
    return first_failed if first_failed is not None else PathLookup(None, None, False)

def lookup_or_report_error(db, raw_arg, cmd):
    """raw_arg is the user argument (or b'.'); returns (Dir, norm) or (None,norm)."""
    norm = normalize_path(raw_arg)
    lk = find_dir(db, norm, log_no_report=True)
    if lk.dir is not None:
        return lk.dir, norm
    if cmd in ('ls', 'ui', 'gui'):
        err(b"The requested path '" + raw_arg + b"' was not found in the database,\n")
        err(b"Please run 'duc info' for a list of available directories.\n")
    else:
        err(b"Requested path not found\n")
    return None, norm

