    def __init__(self):
        self.by_point = {}
        self.points = []  # (point, fstype)
        try:
            with open('/proc/self/mountinfo', 'rb') as fh:
                for line in fh:
                    parts = line.rstrip(b'\n').split(b' ')
                    if len(parts) < 5: continue
                    point = _unescape_mount(parts[4])
                    try:
                        dash = parts.index(b'-')
                        fstype = parts[dash+1]
                    except Exception:
                        continue
                    self.by_point[point] = fstype
                    self.points.append((point, fstype))
        except Exception:
            pass
    def fstype(self, physical_path):
        if physical_path in self.by_point:
            return self.by_point[physical_path]
