# Indexing
@dataclass
class ScanResult:
    dev: int
    ino: int
    total_apparent: int
    total_actual: int
    total_count: int

class Indexer:
    def __init__(self, db, opts, effective_uid):
        self.db = db
        self.opts = opts
        self.effective_uid = effective_uid
        self.excludes = [v for v in opts.get('exclude', [])]
        self.fs_exclude = []
        self.fs_include = []
        for v in opts.get('fs_exclude', []):
            self.fs_exclude.extend(v.split(b','))
        for v in opts.get('fs_include', []):
            self.fs_include.extend(v.split(b','))
        self.check_hard = bool(opts.get('check_hard_links'))
        self.seen_hard = set()
        self.hide = bool(opts.get('hide_file_names'))
        self.one_fs = bool(opts.get('one_file_system'))
        self.max_depth = c_atoi(opts.get('max_depth', b'0')) if opts.get('max_depth') is not None else 0
        self.buckets = c_atoi(opts.get('buckets', b'48')) if opts.get('buckets') is not None else 48
        self.topn_n = c_atoi(opts.get('topn', b'10')) if opts.get('topn') is not None else 10
        self.dry = bool(opts.get('dry_run'))
        self.progress = bool(opts.get('progress'))
        self.bytes_mode = bool(opts.get('bytes'))
        self.mounts = Mounts()
        self.rep = None
        self.topn_candidates = []  # ascending by size
        self.prog_pos = 0
        self.prog_last = 0.0
        self.prog_files = 0
        self.prog_dirs = 0
        self.prog_actual = 0

    # progress ------------------------------------------------------------
    def progress_update(self, force=False):
        if not self.progress:
            return
        now = time.monotonic()
        if not force and self.prog_last and now - self.prog_last < 0.1:
            return
        self.prog_last = now
        bar = bytearray(b'--------')
        bar[self.prog_pos % 8] = ord('#')
        self.prog_pos += 1
        if self.rep is not None:
            files = self.rep.file_count; dirs = self.rep.dir_count; act = self.rep.size_actual
        else:
            files = dirs = act = 0
        fs = human_count(files, bytes_mode=self.bytes_mode)
        ds = human_count(dirs, bytes_mode=self.bytes_mode)
        msg = (b'\x1b[K[' + bytes(bar) + b'] Indexed ' + human_size_b(act, bytes_mode=self.bytes_mode, upper=False) +
               b' in ' + fs + b' files and ' + ds + b' directories\r')
        out(msg)
        try: sys.stdout.buffer.flush()
        except Exception: pass

    def message_path(self, fs_path, base_name):
        # Matches the original's use of realpath() for skip messages.
        if log.level < LOG_WARNING:
            return realpath_bytes(fs_path)
        if not realpath_strict_ok(fs_path):
            log.warn(b'Cannot determine realpath of: ' + base_name + b'\n')
        return realpath_bytes(fs_path)

    def warn_skipping(self, fs_path, base_name, reason):
        p = self.message_path(fs_path, base_name)
        log.warn(b'skipping ' + p + b': ' + reason + b'\n')

    def topn_add(self, fs_path, size):
        if self.topn_n <= 0:
            return
        if size <= 10240:
            return
        name = realpath_bytes(fs_path)
        cand = self.topn_candidates
        if len(cand) >= self.topn_n and cand and size <= cand[0][1]:
            return
        # insert ascending (after equal sizes)
        idx = len(cand)
        while idx > 0 and cand[idx-1][1] > size:
            idx -= 1
        cand.insert(idx, (name, size))
        if len(cand) > self.topn_n:
            cand.pop(0)

    def histogram_add(self, size):
        if self.buckets <= 0:
            # Still warn in a well-defined way; original behaviour for
            # non-positive bucket counts is not useful to emulate exactly.
            return
        hist = self.rep.histogram
        if size <= 1:
            bkt = 0
        else:
            bkt = size.bit_length() - 1
        if bkt >= self.buckets:
            log.warn(b'File sizes large enough we ran out of histogram buckets ' + str(self.buckets).encode() +
                     b', please increase the number of buckets and re-run your indexing.\n')
            return
        if bkt < len(hist):
            hist[bkt] += 1

    def scan_dir(self, fs_path, debug_name, parent_dev, parent_ino, depth, dir_stat, is_root=False):
        # Open the directory first (as the original does).
        try:
            with os.scandir(fs_path) as it:
                entries = list(it)
        except OSError as e:
            reason = os.strerror(e.errno).encode() if e.errno else str(e).encode()
            base = debug_name if not is_root else fs_path.rstrip(b'/').split(b'/')[-1] if fs_path != b'/' else b'/'
            # For the root, the original reports the physical path directly.
            if is_root:
                p = realpath_bytes(fs_path) if realpath_strict_ok(fs_path) else self.message_path(fs_path, base)
                log.warn(b'skipping ' + p + b': ' + reason + b'\n')
            else:
                self.warn_skipping(fs_path, base, reason)
            return None
        except Exception as e:
            return None
        if dir_stat is None:
            try:
                dir_stat = os.stat(fs_path)
            except Exception:
                return None
        dev = int(dir_stat.st_dev); ino = int(dir_stat.st_ino)
        log.debug(b'>> ' + debug_name + b'\n')
        own_actual = int(getattr(dir_stat, 'st_blocks', 0)) * 512
        self.rep.dir_count += 1
        self.rep.size_actual += own_actual
        total_app = 0
        total_act = own_actual
        total_cnt = 1
        stored = []
        for entry in entries:
            name = entry.name  # bytes because fs_path is bytes
            if name in (b'.', b'..'):
                continue
            child_fs = join_path(fs_path, name)
            try:
                st = entry.stat(follow_symlinks=False)
            except Exception:
                try:
                    st = os.lstat(child_fs)
                except OSError as e:
                    reason = os.strerror(e.errno).encode() if e.errno else b''
                    self.warn_skipping(child_fs, name, reason)
                    continue
            mode = st.st_mode
            if stat.S_ISDIR(mode): typ = TYPE_DIR
            elif stat.S_ISLNK(mode): typ = TYPE_LNK
            elif stat.S_ISREG(mode): typ = TYPE_REG
            elif stat.S_ISFIFO(mode): typ = TYPE_FIFO
            elif stat.S_ISSOCK(mode): typ = TYPE_SOCK
            elif stat.S_ISCHR(mode): typ = TYPE_CHR
            elif stat.S_ISBLK(mode): typ = TYPE_BLK
            else: typ = TYPE_UNKNOWN
            # 1) name exclusion
            excluded = False
            for pat in self.excludes:
                try:
                    import fnmatch as _fm
                    if _fm.fnmatchcase(name, pat):
                        excluded = True; break
                except Exception:
                    continue
            if excluded:
                self.warn_skipping(child_fs, name, b'Excluded by user')
                continue
            # 2) filesystem boundary checks for directories
            if typ == TYPE_DIR and int(st.st_dev) != dev:
                fst = self.mounts.fstype(realpath_bytes(child_fs))
                if fst and fst in self.fs_exclude:
                    self.warn_skipping(child_fs, name, b"File system type '" + fst + b"' is excluded")
                    continue
                if self.fs_include and fst not in self.fs_include:
                    self.warn_skipping(child_fs, name, b"File system type '" + fst + b"' is not included")
                    continue
                if self.one_fs:
                    self.warn_skipping(child_fs, name, b'Not crossing file system boundaries')
                    continue
            # 3) owner filter
            if self.effective_uid is not None and int(st.st_uid) != self.effective_uid:
                continue
            if typ == TYPE_DIR:
                res = self.scan_dir(child_fs, name, dev, ino, depth + 1, st, is_root=False)
                if res is None:
                    continue
                ent = Ent(name, res.total_apparent, res.total_actual, res.total_count, TYPE_DIR, res.dev, res.ino)
                total_app += res.total_apparent; total_act += res.total_actual; total_cnt += res.total_count
                if self.max_depth == 0 or (depth + 1) < self.max_depth:
                    stored.append(ent)
                self.progress_update(False)
            else:
                # hard links
                if self.check_hard and int(getattr(st, 'st_nlink', 1)) > 1:
                    key = (int(st.st_dev), int(st.st_ino))
                    if key in self.seen_hard:
                        continue
                    self.seen_hard.add(key)
                app = int(st.st_size); act = int(getattr(st, 'st_blocks', 0)) * 512
                ch = classify_char(typ)
                log.debug(ch.rjust(3, b' ') + b' ' + str(app).encode() + b' ' + str(act).encode() + b' ' + name + b'\n')
                self.rep.file_count += 1
                self.rep.size_apparent += app; self.rep.size_actual += act
                self.histogram_add(app)
                self.topn_add(child_fs, app)
                total_app += app; total_act += act; total_cnt += 1
                stored_name = b'<FILE>' if self.hide else name
                ent = Ent(stored_name, app, act, 1, typ, 0, 0)
                if self.max_depth == 0 or depth < self.max_depth:
                    stored.append(ent)
                self.progress_update(False)
        log.debug(b'<< ' + debug_name + b' actual:' + str(total_app).encode() + b' apparent:' + str(total_act).encode() + b'\n')
        if not self.dry and self.db is not None:
            d = Dir(parent_dev=parent_dev, parent_ino=parent_ino, mtime=int(dir_stat.st_mtime), entries=stored, dev=dev, ino=ino)
            key = f"{dev:x}/{ino:x}".encode()
            try:
                self.db.put(key, encode_dir_blob(d))
            except Exception:
                pass
        return ScanResult(dev, ino, total_app, total_act, total_cnt)

def write_report_globals(db, reports):
    reps = bytearray(); hists = bytearray(); topns = bytearray()
    for r in reports:
        chunk = bytearray(16384)
        chunk[:min(len(r.path), 16383)] = r.path[:16383]
        reps += chunk
        arr = [0] * 512
        for i, v in enumerate(r.histogram[:512]):
            arr[i] = int(v) & ((1 << 64) - 1)
        hists += struct.pack('<512Q', *arr)
        topns += b'\x00' * 8000
    db.put(b'duc_index_reports', bytes(reps))
    db.put(b'duc_index_histograms', bytes(hists))
    db.put(b'duc_index_topn_info\x00', bytes(topns))

def cmd_index(opts, pos):
    if not pos:
        err(b'Required index PATH missing.\n')
        out(CMD_HELP['index'])
        return 1
    # Resolve username / uid (the original crashes on unknown users here).
    effective_uid = None
    username = opts.get('username')
    uid_opt = opts.get('uid')
    if username is not None or uid_opt is not None:
        import pwd
        if username is not None:
            try:
                pw = pwd.getpwnam(username.decode('utf-8', 'surrogateescape'))
                effective_uid = int(pw.pw_uid)
            except Exception:
                segfault()
        if uid_opt is not None:
            uv = c_atoi(uid_opt)
            if uv != 0:
                try:
                    pw = pwd.getpwuid(uv & 0xffffffff)
                    effective_uid = int(pw.pw_uid)
                except Exception:
                    segfault()
    norm_paths = []
    for raw in pos:
        try:
            v = os.statvfs(raw)
        except Exception:
            err(b"Can't run statvfs on " + raw + b'\n')
            return 1
        try:
            if int(v.f_blocks) * int(v.f_frsize) > (1 << 31):
                log.info(b'Found big filesystem\n')
        except Exception:
            pass
        norm_paths.append(normalize_path(raw))
    db = open_db_for('index', opts, write=True)
    if db is None:
        return 1
    dry = bool(opts.get('dry_run'))
    reports = []
    if not dry:
        for p in db.report_paths():
            r = db.get_report(p)
            if r is None:
                r = Report(path=p)
                r.histogram = [0] * max(0, r.buckets)
            reports.append(r)
    indexer = Indexer(db if not dry else db, opts, effective_uid)
    # dry-run still "opens" the db (creating it) but stores nothing.
    indexer.db = db
    for norm in norm_paths:
        rep = Report(path=norm)
        rep.buckets = indexer.buckets if indexer.buckets and indexer.buckets > 0 else 0
        rep.topn_n = indexer.topn_n if indexer.topn_n and indexer.topn_n > 0 else 0
        rep.histogram = [0] * max(0, rep.buckets)
        rep.topn = []
        indexer.rep = rep
        indexer.topn_candidates = []
        start = time.time()
        rep.start_sec = int(start); rep.start_usec = int((start - rep.start_sec) * 1000000)
        res = indexer.scan_dir(norm, norm, 0, 0, 0, None, is_root=True)
        end = time.time()
        rep.end_sec = int(end); rep.end_usec = int((end - rep.end_sec) * 1000000)
        if res is not None:
            rep.dev = res.dev; rep.ino = res.ino
        else:
            rep.dev = 0; rep.ino = 0
            # A failed root contributes nothing (scan_dir returns before counting).
            rep.file_count = 0; rep.dir_count = 0; rep.size_apparent = 0; rep.size_actual = 0
        rep.total_count = rep.file_count + rep.dir_count
        rep.topn = list(indexer.topn_candidates)
        if indexer.progress:
            indexer.progress_update(force=True)
            out(b'\n')
            indexer.prog_last = 0.0
        dur = end - start
        log.info(b'Indexed ' + str(rep.file_count).encode() + b' files and ' + str(rep.dir_count).encode() +
                 b' directories, (' + human_size_b(rep.size_apparent, bytes_mode=indexer.bytes_mode, upper=True) + b' apparent, ' +
                 human_size_b(rep.size_actual, bytes_mode=indexer.bytes_mode, upper=True) + b' actual) in ' + f"{dur:.2f}".encode() + b' secs.\n')
        if not dry:
            replaced = False
            for i, old in enumerate(reports):
                if old.path == rep.path:
                    reports[i] = rep; replaced = True; break
            if not replaced:
                reports.append(rep)
            try:
                db.put(rep.path, encode_report_blob(rep))
                write_report_globals(db, reports)
                db.commit()
            except Exception:
                pass
    db.close()
    return 0

