# ls
def terminal_width():
    env = getattr(os, 'environb', {})
    if env and b'COLUMNS' in env:
        return c_atoi(env[b'COLUMNS'])
    if 'COLUMNS' in os.environ:
        return c_atoi(os.environ['COLUMNS'].encode())
    try:
        import shutil
        # Only query a real tty; otherwise the original defaults to 80.
        if sys.stdout.isatty():
            return shutil.get_terminal_size(fallback=(80, 24)).columns
    except Exception:
        pass
    return 80

def size_field(n, bytes_mode, count_mode):
    s = human_size(n, bytes_mode=bytes_mode, count_mode=count_mode)
    width = 12 if bytes_mode else 6
    return s.rjust(width, b' ')

def ls_mode(opts):
    if opts.get('count'):
        return 'count'
    if opts.get('apparent'):
        return 'apparent'
    return 'actual'

def classify_suffix(e, do_classify):
    return classify_char(e.type) if do_classify else b''

class LsPrinter:
    def __init__(self, db, opts):
        self.db = db
        self.opts = opts
        self.bytes_mode = bool(opts.get('bytes'))
        self.count_mode = bool(opts.get('count'))
        self.mode = ls_mode(opts)
        self.name_sort = bool(opts.get('name_sort'))
        self.do_classify = bool(opts.get('classify'))
        self.do_graph = bool(opts.get('graph'))
        self.recursive = bool(opts.get('recursive'))
        self.ascii = bool(opts.get('ascii'))
        self.dirs_only = bool(opts.get('dirs_only'))
        self.full_path = bool(opts.get('full_path'))
        self.levels = c_atoi(opts.get('levels', b'4')) if opts.get('levels') is not None else 4
        self.color = bool(opts.get('color')) and sys.stdout.isatty()
        self.term_width = terminal_width()

    def color_for(self, frac_num, frac_den):
        if not self.color:
            return b''
        if frac_den == 0:
            frac = 1.0
        else:
            frac = frac_num / frac_den if frac_den else 0.0
        if frac >= 0.5:
            return b'\x1b[31m'
        if frac >= 0.125:
            return b'\x1b[33m'
        return b''

    def print_line(self, size_val, label, group_max, graph_width, max_label_graph_len=None):
        # label is everything after "SIZE " (prefix + name + classify),
        # already padded by the caller for graph alignment if needed.
        color = self.color_for(size_val, group_max)
        sf = size_field(size_val, self.bytes_mode, self.count_mode)
        if self.color:
            line = color + sf + b'\x1b[0m ' + label
        else:
            line = sf + b' ' + label
        if self.do_graph and not self.full_path:
            w = graph_width
            if w < 0: w = 0
            plus = 0
            if group_max:
                plus = int(size_val * w / group_max) if group_max else 0
                if plus > w: plus = w
            bar = b'+' * plus + b' ' * (w - plus)
            if self.color:
                line += b' [' + color + bar + b'\x1b[0m]'
            else:
                line += b' [' + bar + b']'
        out(line + b'\n')

    def branch_segment(self, is_first, is_last):
        if self.ascii:
            if is_first and not is_last: return '`+- '.encode()
            if is_last: return ' `- '.encode()
            return ' |- '.encode()
        else:
            if is_first and not is_last: return '╰┬─ '.encode()
            if is_last: return ' ╰─ '.encode()
            return ' ├─ '.encode()

    def ancestor_segment(self, ancestor_is_last):
        if ancestor_is_last:
            return b'    '
        return ' │  '.encode() if not self.ascii else b' |  '

    def print_dir_listing(self, dir_obj, depth, trail_segments, rel_prefix):
        """Print entries of dir_obj.  depth=0 for the queried directory.
           trail_segments: list of ancestor-is_last flags (for depth>0)."""
        if depth > self.levels:
            return
        if self.levels < 0:
            return
        entries_all = dir_obj.entries
        entries_sorted = sorted_entries(entries_all, mode=self.mode, name_sort=self.name_sort)
        # group statistics are over all entries (before dirs-only filtering)
        group_max = 0
        max_name = 0
        for e in entries_all:
            v = ent_value(e, self.mode)
            if v > group_max: group_max = v
            nl = len(e.name) + (1 if self.do_classify else 0)
            if nl > max_name: max_name = nl
        # graph width: matches observed constant using an assumed tree
        # indent of 4*(depth+1) even in non-recursive mode.
        if self.do_graph and not self.full_path:
            size_w = 12 if self.bytes_mode else 6
            assumed_prefix = 4 * (depth + 1)
            graph_w = self.term_width - 1 - (size_w + 1 + assumed_prefix + max_name + 1 + 2)
            if graph_w < 0: graph_w = 0
        else:
            graph_w = 0
        printed = []
        for e in entries_sorted:
            if self.dirs_only and e.type != TYPE_DIR:
                continue
            printed.append(e)
        for idx, e in enumerate(printed):
            is_first = (idx == 0)
            is_last = (idx == len(printed) - 1)
            name_disp = e.name + classify_suffix(e, self.do_classify)
            if self.recursive and self.full_path:
                full = join_path(rel_prefix, e.name) if rel_prefix else e.name
                # join_path treats a leading name as under '/', fix for relative
                if rel_prefix:
                    full = rel_prefix + b'/' + e.name
                else:
                    full = e.name
                label = full + classify_suffix(e, self.do_classify)
            elif self.recursive:
                prefix = b''.join(self.ancestor_segment(x) for x in trail_segments)
                prefix += self.branch_segment(is_first, is_last)
                label = prefix + name_disp
            else:
                label = name_disp
            if self.do_graph and not self.full_path:
                # Pad the *name field* to max_name.  Label layout differs
                # for recursive (prefix precedes the name field).
                if self.recursive:
                    prefix = b''.join(self.ancestor_segment(x) for x in trail_segments) + self.branch_segment(is_first, is_last)
                    pad = max_name - len(name_disp)
                    label = prefix + name_disp + b' ' * (pad if pad > 0 else 0)
                else:
                    pad = max_name - len(name_disp)
                    label = name_disp + b' ' * (pad if pad > 0 else 0)
            self.print_line(ent_value(e, self.mode), label, group_max, graph_w)
            if self.recursive and e.type == TYPE_DIR and depth < self.levels:
                child = self.db.get_dir(e.dev, e.ino)
                if child is not None:
                    new_rel = (rel_prefix + b'/' + e.name) if rel_prefix else e.name
                    self.print_dir_listing(child, depth + 1, trail_segments + [is_last], new_rel)

    def print_directory_itself(self, dir_obj, raw_arg):
        if self.mode == 'apparent': v = dir_obj.total_apparent
        elif self.mode == 'count': v = dir_obj.total_count
        else: v = dir_obj.total_actual
