# ---------------------------------------------------------------------------
# CGI
CGI_CSS = b"""body { font-family: "arial", "sans-serif"; font-size: 11px; }
table, thead, tbody, tr, td, th { font-size: inherit; font-family: inherit; }
#main { display:table-cell; }
#index { border-bottom: solid 1px #777777; }
#index table td { padding-left: 5px; }
#graph { float: left; }
#list { float: left; }
#list table { margin-left: auto; margin-right: auto; }
#list table td { padding-left: 5px; }
#list table td.name, th.name { text-align: left; }
#list table td.size, th.size { text-align: right; }
#tooltip { display: none; position: absolute; background-color: white;
           border: solid 1px black; padding: 3px; white-space: nowrap; }
"""

def url_decode(s):
    out = bytearray(); i = 0
    while i < len(s):
        c = s[i]
        if c == 37 and i + 2 < len(s) + 0 and i + 2 < len(s):
            try:
                out.append(int(s[i+1:i+3], 16)); i += 3; continue
            except Exception:
                pass
        if c == 43:
            out.append(32)
        else:
            out.append(c)
        i += 1
    return bytes(out)

def parse_query(qs):
    params = {}
    if not qs:
        return params
    for pair in qs.split(b'&'):
        if b'=' in pair:
            k, v = pair.split(b'=', 1)
        else:
            k, v = pair, b''
        params[url_decode(k)] = url_decode(v)
    return params

def cmd_cgi(opts, pos):
    envb = getattr(os, 'environb', {})
    if b'GATEWAY_INTERFACE' not in envb and 'GATEWAY_INTERFACE' not in os.environ:
        err(b"The 'cgi' subcommand is used for integrating Duc into a web server.\n")
        err(b'Please refer to the documentation for instructions how to install and configure.\n')
        return 1
    db = open_db_for('cgi', opts, write=False)
    if db is None:
        return 1
    qs = envb.get(b'QUERY_STRING', b'') if envb else os.environ.get('QUERY_STRING', '').encode()
    script = envb.get(b'SCRIPT_NAME', b'') if envb else os.environ.get('SCRIPT_NAME', '').encode()
    params = parse_query(qs)
    cmd_q = params.get(b'cmd', b'')
    path_q = params.get(b'path')
    # Only the index and graph (cmd=index) views produce output; other
    # cmd values observed produce an empty successful response.
    if cmd_q not in (b'', b'index') and b'x' not in params:
        db.close(); return 0
    bytes_mode = bool(opts.get('bytes'))
    mode = 'count' if opts.get('count') else ('apparent' if opts.get('apparent') else 'actual')
    out(b'Content-Type: text/html\n\n')
    out(b'<!DOCTYPE html>\n<head>\n  <meta charset="utf-8" />\n')
    # header include / css
    if opts.get('header'):
        try:
            with open(opts['header'], 'rb') as fh: out(fh.read())
        except Exception:
            pass
    if opts.get('css_url'):
        out(b'<link rel="stylesheet" href="' + opts['css_url'] + b'">\n')
    else:
        out(b'<style>\n' + CGI_CSS + b'</style>\n')
    graph_dir = None; graph_norm = None
    show_graph = False
    if cmd_q == b'index' and path_q:
        show_graph = True
    if b'x' in params and path_q:
        show_graph = True
    if show_graph:
        graph_norm = normalize_path(path_q)
        lk = find_dir(db, graph_norm, log_no_report=False)
        graph_dir = lk.dir
        out(b'<script>\n')
        out(b'  window.onload = function() {\n')
        out(b"    var img = document.getElementById('duc_canvas');\n")
        out(b"    var tt = document.getElementById('tooltip');\n")
        out(b'    var timer;\n')
        out(b'    img.onmousedown = function(e) {\n')
        out(b'      if(e.button == 0) {\n')
        out(b'        var rect = img.getBoundingClientRect(img);\n')
        out(b'        var x = e.clientX - rect.left;\n')
        out(b'        var y = e.clientY - rect.top;\n')
        out(b"        window.location = '?x=' + x + '&y=' + y + '&path=" + (graph_norm or b'') + b"';\n")
        out(b'      }\n')
        out(b'    }\n')
        out(b'  };\n')
        out(b'</script>\n')
    out(b'</head>\n<body>\n<div id=main>\n')
    # Index table
    out(b'<div id=index> <table>\n')
    out(b'  <tr>\n   <th>Path</th>\n   <th>Size</th>\n   <th>Files</th>\n   <th>Directories</th>\n   <th>Date</th>\n   <th>Time</th>\n  </tr>\n')
    for p in db.report_paths():
        r = db.get_report(p)
        if r is None: r = Report(path=p)
        dt = format_date_time(r.start_sec)
        date, tm = dt[:10], dt[11:]
        sizev = r.size_apparent if mode == 'apparent' else r.size_actual
        if mode == 'count':
            size = human_count(r.total_count, bytes_mode=bytes_mode)
        else:
            size = human_size(sizev, bytes_mode=bytes_mode)
        out(b'  <tr>\n')
        out(b'   <td><a href="' + script + b'?cmd=index&path=' + r.path + b'">' + r.path + b'</a></td>\n')
        out(b'   <td>' + size + b'</td>\n')
        out(b'   <td>' + str(r.file_count).encode() + b'</td>\n')
        out(b'   <td>' + str(r.dir_count).encode() + b'</td>\n')
        out(b'   <td>' + date + b'</td>\n')
        out(b'   <td>' + tm + b'</td>\n')
        out(b'  </tr>\n')
    out(b' </table>\n')
    if show_graph and graph_dir is not None:
        builder = GraphBuilder(db, opts, graph_dir, graph_norm)
        builder.build()
        out(b'<div id=graph>\n')
        out(render_html(builder, for_cgi=True))
        out(b'</script>\n')
        out(b'</div>\n')
        if opts.get('list'):
            out(b'<div id=list>\n<table>\n')
            out(b' <tr><th class=name>Name</th><th class=size>Size</th></tr>\n')
            for e in sorted_entries(graph_dir.entries, mode=mode):
                sz = human_size(ent_value(e, mode), bytes_mode=bytes_mode, count_mode=(mode == 'count'))
                if e.type == TYPE_DIR:
                    child_path = join_path(graph_norm, e.name)
                    name_html = b'<a href="' + script + b'?cmd=index&path=' + child_path + b'">' + e.name + b'</a>'
                else:
                    name_html = e.name
                out(b' <tr><td class=name>' + name_html + b'</td><td class=size>' + sz + b'</td></tr>\n')
            out(b'</table>\n</div>\n')
    out(b'</div>\n</div>\n')
    if opts.get('footer'):
        try:
            with open(opts['footer'], 'rb') as fh: out(fh.read())
        except Exception:
            pass
    out(b'</body>\n</html>\n')
    db.close()
    return 0

# ---------------------------------------------------------------------------
# GUI (no X toolkit available; reproduce the no-display behaviour)
def cmd_gui(opts, pos):
    db = open_db_for('gui', opts, write=False)
    if db is None:
        return 1
    raw = pos[0] if pos else b'.'
    dir_obj, norm = lookup_or_report_error(db, raw, 'gui')
    if dir_obj is None:
        db.close(); return 1
    db.close()
    err(b'ERROR: Could not open display\n')
    return 1

# ---------------------------------------------------------------------------
# UI (ncurses)
def cmd_ui(opts, pos):
    db = open_db_for('ui', opts, write=False)
    if db is None:
        return 1
    raw = pos[0] if pos else b'.'
    dir_obj, norm = lookup_or_report_error(db, raw, 'ui')
    if dir_obj is None:
        db.close(); return 1
    # Terminal setup
    term = os.environ.get('TERM', '')
    try:
        import curses
    except Exception:
        err(b'Error opening terminal: ' + (term.encode() if term else b'unknown') + b'.\n')
        db.close(); return 1
    state = {
        'db': db, 'opts': opts, 'norm': norm, 'dir': dir_obj,
        'apparent': bool(opts.get('apparent')), 'bytes': bool(opts.get('bytes')),
        'count': bool(opts.get('count')), 'name_sort': bool(opts.get('name_sort')),
        'no_color': bool(opts.get('no_color')), 'topn_view': False,
    }
    try:
        rc = _ui_main(state)
    except Exception as e:
        # curses raises curses.error for a bad terminal
        try:
            import curses as _c
            _c.endwin()
        except Exception:
            pass
        err(b'Error opening terminal: ' + (term.encode() if term else b'unknown') + b'.\n')
        db.close(); return 1
    db.close()
    return rc

def _ui_main(state):
    import curses
    db = state['db']
    # Directory stack of (norm_path, Dir)
    stack = [(state['norm'], state['dir'])]
    def mode():
        return 'count' if state['count'] else ('apparent' if state['apparent'] else 'actual')
    def entries_for(d):
        return sorted_entries(d.entries, mode=mode(), name_sort=state['name_sort'])
    def topn_entries():
        ents = []
        for p in db.report_paths():
            r = db.get_report(p)
            if r:
                for name, sz in reversed(r.topn):
                    if name:
                        ents.append((name, sz))
        return ents
    def run(stdscr):
        try:
            curses.curs_set(0)
        except Exception:
            pass
        use_color = False
        if not state['no_color']:
            try:
                curses.start_color(); curses.use_default_colors()
                curses.init_pair(1, curses.COLOR_BLACK, curses.COLOR_CYAN)
                use_color = True
            except Exception:
                use_color = False
        sel = 0; off = 0; show_help = False
        while True:
            norm, d = stack[-1]
            if state['topn_view']:
                items = topn_entries()
            else:
                items = entries_for(d)
            stdscr.erase()
            h, w = stdscr.getmaxyx()
            if show_help:
                lines = [
                    'duc ui help', '',
                    '    up, pgup, j:     move cursor up',
                    '    down, pgdn, k:   move cursor down',
                    '    home, 0:         move cursor to top',
                    '    end, $:          move cursor to bottom',
                    '    left, backspace: go up to parent directory (..)',
                    '    right, enter:    descent into selected directory',
                    '    a:               toggle between actual and apparent disk usage',
                    '    b:               toggle between exact and abbreviated sizes',
                    '    c:               Toggle between file size and file count',
                    '    h:               show help. press \'q\' to return to the main screen',
                    '    n:               toggle sort order between \'size\' and \'name\'',
                    '    o:               try to open the file using xdg-open',
                    '    q, escape:       quit',
                    '    t:               toggle between regular view and TopN files by size',
                ]
                for i, ln in enumerate(lines[:max(0, h-1)]):
                    try: stdscr.addstr(i, 0, ln[:max(0, w-1)])
                    except Exception: pass
            else:
                # Header: total size and path (approximates the original)
                if state['topn_view']:
                    title = 'TopN files by size'
                else:
                    tot = ent_value_from_dir(d, mode())
                    title = human_size(tot, bytes_mode=state['bytes'], count_mode=state['count']).decode('utf-8', 'replace') + '  ' + norm.decode('utf-8', 'replace')
                try: stdscr.addstr(0, 0, title[:max(0, w-1)])
                except Exception: pass
                rows = max(0, h - 1)
                if sel >= len(items): sel = max(0, len(items) - 1)
                if sel < off: off = sel
                if rows and sel >= off + rows: off = sel - rows + 1
                # group max for a simple graph-less listing
                for i in range(off, min(len(items), off + rows)):
                    y = 1 + (i - off)
