# UI (ncurses)
def cmd_ui(opts, pos):
    db = open_db_for('ui', opts, write=False)
    if db is None:
        return 1
    raw = pos[0] if pos else b'.'
    dir_obj, norm = lookup_or_report_error(db, raw, 'ui')
    if dir_obj is None:
        db.close(); return 1
    # Terminal setup
    term = os.environ.get('TERM', '')
    try:
        import curses
    except Exception:
        err(b'Error opening terminal: ' + (term.encode() if term else b'unknown') + b'.\n')
        db.close(); return 1
    state = {
        'db': db, 'opts': opts, 'norm': norm, 'dir': dir_obj,
        'apparent': bool(opts.get('apparent')), 'bytes': bool(opts.get('bytes')),
        'count': bool(opts.get('count')), 'name_sort': bool(opts.get('name_sort')),
        'no_color': bool(opts.get('no_color')), 'topn_view': False,
    }
    try:
        rc = _ui_main(state)
    except Exception as e:
        # curses raises curses.error for a bad terminal
        try:
            import curses as _c
            _c.endwin()
        except Exception:
            pass
        err(b'Error opening terminal: ' + (term.encode() if term else b'unknown') + b'.\n')
        db.close(); return 1
    db.close()
    return rc

def _ui_main(state):
    import curses
    db = state['db']
    # Directory stack of (norm_path, Dir)
    stack = [(state['norm'], state['dir'])]
    def mode():
        return 'count' if state['count'] else ('apparent' if state['apparent'] else 'actual')
    def entries_for(d):
        return sorted_entries(d.entries, mode=mode(), name_sort=state['name_sort'])
    def topn_entries():
        ents = []
        for p in db.report_paths():
            r = db.get_report(p)
            if r:
                for name, sz in reversed(r.topn):
                    if name:
                        ents.append((name, sz))
        return ents
    def run(stdscr):
        try:
            curses.curs_set(0)
        except Exception:
            pass
        use_color = False
        if not state['no_color']:
            try:
                curses.start_color(); curses.use_default_colors()
                curses.init_pair(1, curses.COLOR_BLACK, curses.COLOR_CYAN)
                use_color = True
            except Exception:
                use_color = False
        sel = 0; off = 0; show_help = False
        while True:
            norm, d = stack[-1]
            if state['topn_view']:
                items = topn_entries()
            else:
                items = entries_for(d)
            stdscr.erase()
            h, w = stdscr.getmaxyx()
            if show_help:
                lines = [
                    'duc ui help', '',
                    '    up, pgup, j:     move cursor up',
                    '    down, pgdn, k:   move cursor down',
                    '    home, 0:         move cursor to top',
                    '    end, $:          move cursor to bottom',
                    '    left, backspace: go up to parent directory (..)',
                    '    right, enter:    descent into selected directory',
                    '    a:               toggle between actual and apparent disk usage',
                    '    b:               toggle between exact and abbreviated sizes',
                    '    c:               Toggle between file size and file count',
                    '    h:               show help. press \'q\' to return to the main screen',
                    '    n:               toggle sort order between \'size\' and \'name\'',
                    '    o:               try to open the file using xdg-open',
                    '    q, escape:       quit',
                    '    t:               toggle between regular view and TopN files by size',
                ]
                for i, ln in enumerate(lines[:max(0, h-1)]):
                    try: stdscr.addstr(i, 0, ln[:max(0, w-1)])
                    except Exception: pass
            else:
                # Header: total size and path (approximates the original)
                if state['topn_view']:
                    title = 'TopN files by size'
                else:
                    tot = ent_value_from_dir(d, mode())
                    title = human_size(tot, bytes_mode=state['bytes'], count_mode=state['count']).decode('utf-8', 'replace') + '  ' + norm.decode('utf-8', 'replace')
                try: stdscr.addstr(0, 0, title[:max(0, w-1)])
                except Exception: pass
                rows = max(0, h - 1)
                if sel >= len(items): sel = max(0, len(items) - 1)
                if sel < off: off = sel
                if rows and sel >= off + rows: off = sel - rows + 1
                # group max for a simple graph-less listing
                for i in range(off, min(len(items), off + rows)):
                    y = 1 + (i - off)
                    if state['topn_view']:
                        name, sz = items[i]
                        disp = human_size(sz, bytes_mode=state['bytes']).decode().rjust(12 if state['bytes'] else 6) + ' ' + name.decode('utf-8', 'replace')
                    else:
                        e = items[i]
                        v = ent_value(e, mode())
                        disp = human_size(v, bytes_mode=state['bytes'], count_mode=state['count']).decode().rjust(12 if state['bytes'] else 6) + ' ' + e.name.decode('utf-8', 'replace') + ('/' if e.type == TYPE_DIR else '')
                    attr = curses.A_REVERSE if i == sel else 0
                    try: stdscr.addstr(y, 0, disp[:max(0, w-1)], attr)
                    except Exception: pass
            stdscr.refresh()
            try:
                ch = stdscr.getch()
            except Exception:
                return 0
            if show_help:
                if ch in (ord('q'), 27):
                    show_help = False
                continue
            if ch in (ord('q'), 27):
                return 0
            elif ch in (curses.KEY_UP, curses.KEY_PPAGE, ord('j')):
                # Original: j moves up (sic), k moves down.
                if ch == curses.KEY_PPAGE:
                    sel = max(0, sel - max(1, (h - 1)))
                else:
                    sel = max(0, sel - 1)
            elif ch in (curses.KEY_DOWN, curses.KEY_NPAGE, ord('k')):
                if ch == curses.KEY_NPAGE:
                    sel = min(max(0, len(items) - 1), sel + max(1, (h - 1)))
                else:
                    sel = min(max(0, len(items) - 1), sel + 1)
            elif ch in (curses.KEY_HOME, ord('0')):
                sel = 0
            elif ch in (curses.KEY_END, ord('$')):
                sel = max(0, len(items) - 1)
            elif ch in (curses.KEY_LEFT, 127, curses.KEY_BACKSPACE, 8):
                if len(stack) > 1:
                    stack.pop(); sel = 0; off = 0
                elif not state['topn_view']:
                    # Try parent via stored parent dev/ino
                    pd = db.get_dir(d.parent_dev, d.parent_ino) if (d.parent_dev or d.parent_ino) else None
                    if pd is not None:
                        parent = norm.rstrip(b'/').rsplit(b'/', 1)[0] or b'/'
                        stack[-1] = (parent, pd); sel = 0; off = 0
            elif ch in (curses.KEY_RIGHT, 10, 13, curses.KEY_ENTER):
                if not state['topn_view'] and items and 0 <= sel < len(items):
                    e = items[sel]
                    if e.type == TYPE_DIR:
                        cd = db.get_dir(e.dev, e.ino)
                        if cd is not None:
                            stack.append((join_path(norm, e.name), cd)); sel = 0; off = 0
            elif ch == ord('a'):
                state['apparent'] = not state['apparent']
            elif ch == ord('b'):
                state['bytes'] = not state['bytes']
            elif ch == ord('c'):
                state['count'] = not state['count']
            elif ch == ord('h'):
                show_help = True
            elif ch == ord('n'):
                state['name_sort'] = not state['name_sort']; sel = 0; off = 0
            elif ch == ord('o'):
                if not state['topn_view'] and items and 0 <= sel < len(items):
                    try:
                        import subprocess
                        subprocess.Popen(['xdg-open', os.fsdecode(join_path(norm, items[sel].name))], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                    except Exception:
                        pass
            elif ch == ord('t'):
                state['topn_view'] = not state['topn_view']; sel = 0; off = 0
    curses.wrapper(run)
    return 0

